    if(input.matches('[data-checklist-view-width]')){c.updateChecklistViewWidth(Number(input.value));return;}
    if(input.matches('[data-checklist-font]')){c.updateBlock({fontSize:Number(input.value)});return;}if(input.matches('[data-checklist-color]')){c.updateBlock({color:input.value});return;}if(input.matches('[data-checklist-indicator]')){c.updateBlock({indicator:input.value as 'check'});return;}if(input.matches('[data-checklist-launcher-label]')){c.updateBlock({text:input.value});return;}
    if(this.step.contains(input)){c.updateChecklist(next=>{if(input.matches('[data-checklist-title]'))next.title=input.value;if(input.matches('[data-checklist-description]'))next.description=input.value;if(input.matches('[data-checklist-completion-title]'))next.completionMessage.title=input.value;if(input.matches('[data-checklist-completion-description]'))next.completionMessage.description=input.value;if(input.matches('[data-checklist-ack]'))next.completionMessage.acknowledgeLabel=input.value;if(input.matches('[data-checklist-position]'))next.behavior.position=input.value as 'bottom-right';if(input.matches('[data-checklist-order]'))next.behavior.order=input.value as 'any';if(input.matches('[data-checklist-initial]'))next.behavior.initialState=input.value as 'expanded';if(input.matches('[data-checklist-dismissible]'))next.behavior.dismissible=(input as HTMLInputElement).checked;if(input.matches('[data-checklist-remaining]'))next.behavior.showRemainingCount=(input as HTMLInputElement).checked;});return;}
    if(!item||!this.task.contains(input))return;
    const next=structuredClone(item);if(input.matches('[data-checklist-task-title]'))next.title=input.value;if(input.matches('[data-checklist-task-description]'))next.description=input.value;
    if(input.matches('[data-checklist-action]'))next.action=input.value==='none'?{type:'none'}:input.value==='launch_guide'?{type:'launch_guide',experienceId:this.references.guides[0]?.id??''}:{type:input.value as 'navigate'|'open_url',url:input.value==='navigate'?'/':location.origin};
    if(input.matches('[data-checklist-action-guide]'))next.action={type:'launch_guide',experienceId:input.value};if(input.matches('[data-checklist-url]')&&'url'in next.action)next.action.url=input.value;
