import type { RuntimeChecklistDefinition } from '../types';
export type ChecklistView = 'expanded' | 'launcher' | 'completion';
export type ChecklistTextRole = 'title' | 'description' | 'launcher-label' | 'remaining-count' | 'completion-title' | 'completion-description';
export type ChecklistControlRole = 'collapse' | 'dismiss' | 'completion-acknowledge';
export type OnsiteChecklistContext = Pick<RuntimeChecklistDefinition, 'title' | 'description' | 'items' | 'behavior' | 'completionMessage'>;
export const checklistCopy = (value: OnsiteChecklistContext) => ({title:value.title,description:value.description??'', 'launcher-label':value.title,'remaining-count':'', 'completion-title':value.completionMessage.title,'completion-description':value.completionMessage.description??''});
export const escapeChecklist = (value:string) => value.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
export const CHECKLIST_CELL_CSS = '.movcues-widget--checklist{width:360px;max-width:calc(100vw - 32px);max-height:calc(100dvh - 32px);overflow:auto;background:var(--movcues-bg,#fff);color:var(--movcues-fg,#111827);border:1px solid var(--movcues-border,#e2e8f0);border-radius:var(--movcues-theme-radius,12px);box-shadow:var(--movcues-theme-shadow,0 12px 40px #0f172a24);font:14px/1.4 var(--movcues-font-body,ui-sans-serif,system-ui)}.movcues-widget [data-movcues-checklist-view]:not(.is-active){display:none!important}.movcues-widget--checklist:has([data-movcues-checklist-view="launcher"].is-active){width:220px}.movcues-widget .movcues-checklist__item{display:flex;align-items:flex-start;gap:10px;width:100%;padding:10px;border:1px solid var(--movcues-border,#e2e8f0);border-radius:var(--movcues-button-radius,8px);background:var(--movcues-surface,#f8fafc);color:inherit;text-align:left;cursor:pointer;font:inherit}.movcues-widget .movcues-checklist__copy{display:grid;gap:3px}.movcues-widget [data-movcues-checklist-item-role="title"]{font-weight:600}.movcues-widget [data-movcues-checklist-item-role="description"]{font-size:.9em;color:var(--movcues-muted,#64748b)}.movcues-widget [data-movcues-checklist-item-role="state"]{display:grid;place-items:center;flex:none;width:22px;height:22px;border:1px solid #94a3b8;border-radius:50%;color:transparent}.movcues-widget [data-state="completed"] [data-movcues-checklist-item-role="state"]{background:#16a34a;border-color:#16a34a;color:#fff}.movcues-widget [data-state="locked"]{opacity:.5;cursor:not-allowed}.movcues-widget .movcues-checklist-progress-track{height:4px;border-radius:4px;background:#e2e8f0;overflow:hidden}.movcues-widget .movcues-checklist-progress-fill{display:block;height:100%;width:var(--movcues-checklist-progress,0%);background:var(--movcues-primary,#2563eb)}.movcues-widget .movcues-checklist-control{border:1px solid var(--movcues-border,#cbd5e1);border-radius:var(--movcues-button-radius,6px);padding:6px 10px;background:var(--movcues-surface,#fff);color:inherit;cursor:pointer;font:inherit}.movcues-widget [data-movcues-checklist-role="completion-acknowledge"]{background:var(--movcues-primary,#2563eb);border-color:var(--movcues-primary,#2563eb);color:var(--movcues-primary-fg,#fff)}.movcues-widget [data-movcues-checklist-view="launcher"]{cursor:pointer}.movcues-widget [hidden]{display:none!important}';
